def count_Substrings(s):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            digit_sum = sum(int(d) for d in substring)
            if digit_sum == len(substring):
                count += 1
            if digit_sum > len(substring) * 9: # Optimization: sum cannot exceed length * 9
                break
    }
    return count

