def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if m == 0 or m == n - 1:
        return 1
    memo = {}

    def compute(n, m):
        if m == 0:
            return 1
        if n == 0:
            return 0
        if (n, m) in memo:
            return memo[n, m]
        res = (m + 1) * compute(n - 1, m) + (n - m) * compute(n - 1, m - 1)
        memo[n, m] = res
        return res
    return compute(n, m)

