    def sum_divisors(n):
        s = 1
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                s += i
                if i * i != n:
                    s += n // i
        return s
    amicable_sum = 0
    for a in range(2, limit):
        b = sum_divisors(a)
        if b > a and b < limit:
            if sum_divisors(b) == a:
                amicable_sum += a + b
    return amicable_sum

def find_length(s):
    max_diff = 0

    for char_to_max in ['0', '1']:
        current_diff = 0
        min_diff = 0
        for char in s:
            if char == char_to_max:
                current_diff += 1
            else:
                current_diff -= 1

            max_diff = max(max_diff, current_diff - min_diff)
            min_diff = min(min_diff, current_diff)

    return max_diff

