def is_majority(nums, n, x):

    def find_first(nums, x):
        low, high = (0, n - 1)
        res = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] >= x:
                if nums[mid] == x:
                    res = mid
                high = mid - 1
            else:
                low = mid + 1
        return res
    first_idx = find_first(nums, x)
    if first_idx == -1:
        return False
    last_idx = n - 1
    check_idx = first_idx + n // 2
    if check_idx < n and nums[check_idx] == x:
        return True
    return False

