def get_total_number_of_sequences(m, n):
    if n == 0:
        return 0

    memo = {}

    def count_sequences(current_val, length_remaining):
        state = (current_val, length_remaining)
        if state in memo:
            return memo[state]

        if length_remaining == 1:
            return 1

        count = 0
        # The next element must be >= 2 * current_val and <= m
        for next_val in range(2 * current_val, m + 1):
            count += count_sequences(next_val, length_remaining - 1)

        memo[state] = count
        return count

    total = 0
    # The first element can be any positive integer from 1 to m
    for start_val in range(1, m + 1):
        total += count_sequences(start_val, n)

    return total

def get_total_number_of_sequences(n, m):
