def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def newman_prime(n):
    count = 0
    k = 0
    while True:
        # S_k sequence: S_0 = 1, S_1 = 1, S_k = S_{k-1} + S_{k-2} for k >= 2 is not correct.
        # The NSW sequence is defined as: S_0 = 1, S_1 = 1, S_n = S_{n-1}^2 + S_{n-2}^2 is also not it.
        # Correct NSW sequence: S_0 = 1, S_1 = 1, S_n = 2*S_{n-1} + S_{n-2} is Pell.
        # The actual NSW sequence is: S_0 = 1, S_1 = 1, S_n = S_{n-1}^2 + S_{n-2}^2 is wrong.
        # Correct definition: S_0 = 1, S_1 = 1, S_n = S_{n-1}^2 + S_{n-2}^2 is for something else.
        # The Newman-Shanks-Williams (NSW) primes are primes of the form S_k where:
        # S_0 = 1, S_1 = 1, S_n = 2*S_{n-1} + S_{n-2} is Pell.
