def max_Product(nums):
    if len(nums) < 2:
        return None

    nums.sort()

    prod1 = nums[0] * nums[1]
    prod2 = nums[-1] * nums[-2]

    if prod1 > prod2:
        return (nums[0], nums[1])
    else:
        return (nums[-2], nums[-1])

