def find_adverb_position(sentence):
    words = nltk.word_tokenize(sentence)
    tagged = nltk.pos_tag(words)

    current_pos = 0
    for word, tag in tagged:
        start = sentence.find(word, current_pos)
        end = start + len(word)
        if tag.startswith('RB'):
            return (start, end, word)
        current_pos = end
    return None

