def cal_sum(n):
    if n < 0:
        return 0
    perrin = [0] * (n + 1)
    perrin[0] = 3
    if n >= 1:
        perrin[1] = 0
    if n >= 2:
        perrin[2] = 2

    for i in range(3, n + 1):
        perrin[i] = perrin[i-2] + perrin[i-3]

    return sum(perrin)

def sumofFactors(n):
    total = 0
