def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = [0] * n

    for i in range(n):
        dp[i] = nums[i]
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)

