def tuple_intersection(list1, list2):
    set1 = {tuple(sorted(t)) for t in list1}
    set2 = {tuple(sorted(t)) for t in list2}
    intersection = set1.intersection(set2)

    result = set()
    for t1 in list1:
        if tuple(sorted(t1)) in intersection:
            result.add(t1)

    return result

