def max_sub_array_sum(arr, n):
    max_so_far = float('-inf')
    current_max = 0

    for x in arr:
        current_max += x
        if max_so_far < current_max:
            max_so_far = current_max
        if current_max < 0:
            current_max = 0

    return max_so_far

