            if num % 2 == 0 and first_even is None:
                first_even = num
            if num % 2 != 0 and first_odd is None:
                first_odd = num

        if first_even is not None and first_odd is None:
            if num % 2 != 0:
                first_odd = num
        elif first_even is not None and first_odd is not None:
            break

    for num in numbers:
        if num % 2 == 0:
            first_even = num
            break
        if num % 2 != 0:
            # This is handled by the other loop logic, but for simplicity:
