def find_kth(arr1, arr2, k):
    if not arr1:
        return arr2[k - 1]
    if not arr2:
        return arr1[k - 1]
    ia = len(arr1) // 2
    ib = len(arr2) // 2
    ma = arr1[ia]
    mb = arr2[ib]
    if ia + ib < k - 1:
        if ma < mb:
            return find_kth(arr1[ia + 1:], arr2, k - ia - 1)
        else:
            return find_kth(arr1, arr2[ib + 1:], k - ib - 1)
    elif ma < mb:
        return find_kth(arr1, arr2[:ib], k)
    else:
        return find_kth(arr1[:ia], arr2, k)

