def get_ludic(n):
    if n < 1:
        return []

    ludic = [1]
    while True:
        # The next ludic number is the smallest integer that cannot be 
        # represented as the sum of two distinct previous ludic numbers.
        sums = set()
        for i in range(len(ludic)):
            for j in range(i + 1, len(ludic)):
                sums.add(ludic[i] + ludic[j])

        candidate = ludic[-1] + 1
        while candidate in sums:
            candidate += 1

        if candidate > n:
            break
        ludic.append(candidate)

    return ludic

