def largest_subset(nums):
    if not nums:
        return 0
    nums = sorted(nums)
    n = len(nums)
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def triangle_area(radius):
    if radius < 0:
        return None
    # The largest triangle inscribed in a semicircle has the diameter as its base
    # and the radius as its height.
    # Area = 0.5 * base * height = 0.5 * (2 * radius) * radius = radius^2
    return float(radius ** 2)

