def pair_xor_Sum(arr, n):
    total_sum = 0
    for i in range(32):
        count_set_bits = 0
        for num in arr:
            if num & (1 << i):
                count_set_bits += 1

        count_unset_bits = n - count_set_bits
        total_sum += (count_set_bits * count_unset_bits) * (1 << i)

    return total_sum

def heap_sort(arr):

    def heapify(n, i):
        largest = i
        l = 2 * i + 1
        r = 2 * i + 2
        if l < n and arr[i] < arr[l]:
            largest = l
        if r < n and arr[largest] < arr[r]:
            largest = r
        if largest != i:
            arr[i], arr[largest] = (arr[largest], arr[i])
            heapify(n, largest)
    n = len(arr)
    for i in range(n // 2 - 1, -1, -1):
        heapify(n, i)
    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = (arr[0], arr[i])
        heapify(i, 0)
    return arr

