def maxAverageOfPath(matrix):
    N = len(matrix)
    if N == 0:
        return 0

    # In a square matrix of size N*N, any path from (0,0) to (N-1, N-1) 
    # moving only right or down will always visit exactly (2*N - 1) cells.
    # Therefore, maximizing the average is equivalent to maximizing the sum.

    dp = [[0] * N for _ in range(N)]
    dp[0][0] = matrix[0][0]

    for i in range(1, N):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    for j in range(1, N):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    for i in range(1, N):
        for j in range(1, N):
