def toggle_middle_bits(n):
    if n == 0:
        return 0
    binary = bin(n)[2:]
    if len(binary) <= 2:
        return n

    middle = binary[1:-1]
    toggled_middle = "".join('1' if b == '0' else '0' for b in middle)

    result_bin = binary[0] + toggled_middle + binary[-1]
    return int(result_bin, 2)

